DELETE FROM sys_parent_student_relation
WHERE parent_user_id NOT IN (
    SELECT DISTINCT parent_user_id FROM sys_department_parent_binding
) AND EXISTS (
    SELECT 1 FROM sys_department_parent_binding LIMIT 1
)
